<?php
declare(strict_types=1);require_once __DIR__.'/includes/admin_auth.php';require_once __DIR__.'/connection.php';$q=trim($_GET['q']??'');$rows=[];$sql="SELECT u.email,u.first_name,u.middle_name,u.last_name,u.student_id,u.course,u.batch_year,p.city FROM users u LEFT JOIN alumni_profiles p ON p.email=u.email WHERE COALESCE(u.role,'')<>'admin'";if($q!=='')$sql.=" AND (u.email LIKE ? OR u.first_name LIKE ? OR u.last_name LIKE ? OR u.course LIKE ? OR p.city LIKE ?)";$sql.=' ORDER BY u.last_name,u.first_name';$stmt=mysqli_prepare($connection,$sql);if($q!==''){$like="%$q%";mysqli_stmt_bind_param($stmt,'sssss',$like,$like,$like,$like,$like);}mysqli_stmt_execute($stmt);$r=mysqli_stmt_get_result($stmt);while($row=mysqli_fetch_assoc($r))$rows[]=$row;mysqli_stmt_close($stmt);?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Alumni | AlumTrace</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="assets/css/alumtrace.css"></head><body><?php require __DIR__.'/includes/sidebar.php';?><div class="main-wrapper"><?php require __DIR__.'/includes/topbar.php';?><main class="content"><div class="page-head"><h2>Manage Alumni</h2><p>Search and review registered alumni records.</p></div><div class="panel"><form method="get"><input class="input" name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search alumni"><button class="btn btn-primary">Search</button></form></div><div class="panel table-wrap" style="margin-top:22px"><table class="data-table"><thead><tr><th>Name</th><th>Email</th><th>Student ID</th><th>Course</th><th>Batch</th><th>City</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=htmlspecialchars(trim($row['first_name'].' '.$row['middle_name'].' '.$row['last_name']))?></td><td><?=htmlspecialchars($row['email'])?></td><td><?=htmlspecialchars($row['student_id'])?></td><td><?=htmlspecialchars($row['course'])?></td><td><?=htmlspecialchars($row['batch_year'])?></td><td><?=htmlspecialchars($row['city']??'-')?></td></tr><?php endforeach;?></tbody></table></div></main><?php require __DIR__.'/includes/dashboard-footer.php';?></div><script src="assets/js/alumtrace.js"></script></body></html>
